// ── Types ────────────────────────────────────────────────────────────────────

export type Category = 'auto' | 'moto' | 'camion';

/** Alias lowercase per retrocompatibilità con il catalogo esistente */
export type ProductCategory = 'Auto' | 'Moto' | 'Camion';

export interface Product {
  id: string;
  slug: string;
  sku: string;
  /** Titolo del prodotto (già esisteva come `name`) */
  title: string;
  /** @deprecated Usa `title` — mantenuto per retrocompatibilità */
  name: string;
  description: string;
  price: number;           // EUR
  originalPrice?: number;  // se in offerta
  stock: number;
  /** @deprecated Usa `stock > 0` — mantenuto per retrocompatibilità */
  inStock: boolean;
  category: Category;
  /** Categoria con iniziale maiuscola — per retrocompatibilità */
  categoryLabel: ProductCategory;
  brand: string;
  compatibility: string[];
  images: string[];
  /** URL singolo — per retrocompatibilità */
  imageUrl: string;
  tags: string[];
  isNew?: boolean;
  isBestseller?: boolean;
  /** @deprecated Rating mock — mantenuto per retrocompatibilità */
  rating: number;
  /** @deprecated Count mock — mantenuto per retrocompatibilità */
  reviewCount: number;
}

// ── Brands ───────────────────────────────────────────────────────────────────

export const BRANDS = [
  'Bosch',
  'Brembo',
  'NGK',
  'Mann Filter',
  'Ferodo',
  'Magneti Marelli',
  'Gates',
  'SKF',
] as const;

export type Brand = (typeof BRANDS)[number];

// ── Helper per placeholder image ──────────────────────────────────────────────

const img = (sku: string) =>
  `https://placehold.co/600x600/020817/2563EB?text=${encodeURIComponent(sku)}`;

// ── Helper costruttore ────────────────────────────────────────────────────────

function p(
  id: string,
  slug: string,
  sku: string,
  title: string,
  description: string,
  price: number,
  stock: number,
  cat: Category,
  brand: string,
  compatibility: string[],
  tags: string[],
  opts: {
    originalPrice?: number;
    isNew?: boolean;
    isBestseller?: boolean;
    rating?: number;
    reviewCount?: number;
  } = {},
): Product {
  const catLabel = (cat.charAt(0).toUpperCase() + cat.slice(1)) as ProductCategory;
  const image = img(sku);
  return {
    id,
    slug,
    sku,
    title,
    name: title,
    description,
    price,
    originalPrice: opts.originalPrice,
    stock,
    inStock: stock > 0,
    category: cat,
    categoryLabel: catLabel,
    brand,
    compatibility,
    images: [image],
    imageUrl: image,
    tags,
    isNew: opts.isNew,
    isBestseller: opts.isBestseller,
    rating: opts.rating ?? parseFloat((4.3 + Math.random() * 0.7).toFixed(1)),
    reviewCount: opts.reviewCount ?? Math.floor(40 + Math.random() * 500),
  };
}

