// ── Utility Functions ─────────────────────────────────────────────────────────

export function getProductBySlug(slug: string): Product | undefined {
  return PRODUCTS.find((p) => p.slug === slug);
}

export function getProductsByCategory(category: Category | ProductCategory): Product[] {
  const lower = category.toLowerCase() as Category;
  return PRODUCTS.filter((p) => p.category === lower);
}

export function getFeaturedProducts(n = 8): Product[] {
  return PRODUCTS.filter((p) => p.isBestseller).slice(0, n);
}

/** Filtra i prodotti in base ai parametri di ricerca */
export function filterProducts(params: {
  categoria?: string;
  brands?: string[];
  priceMin?: number;
  priceMax?: number;
  q?: string;
}): Product[] {
  const { categoria, brands, priceMin, priceMax, q } = params;

  return PRODUCTS.filter((p) => {
    // Filtro categoria
    if (categoria && categoria !== 'Tutti') {
      if (p.category.toLowerCase() !== categoria.toLowerCase()) return false;
    }

    // Filtro brand
    if (brands && brands.length > 0) {
      if (!brands.includes(p.brand)) return false;
    }

    // Filtro prezzo min
    if (priceMin !== undefined && p.price < priceMin) return false;

    // Filtro prezzo max
    if (priceMax !== undefined && p.price > priceMax) return false;

    // Ricerca testuale
    if (q && q.trim() !== '') {
      const query = q.toLowerCase();
      const haystack = `${p.title} ${p.brand} ${p.sku} ${p.description} ${p.tags.join(' ')}`.toLowerCase();
      if (!haystack.includes(query)) return false;
    }

    return true;
  });
}
